insert into detective_cases(id, slug, title, title_ar, description, description_ar, case_type, difficulty, age_min, age_max, status, created_by, category, estimated_minutes, briefing, briefing_ar, objective, objective_ar, cover_image_path) values ('8b5f1606-cfc6-5bcf-9471-0a13d531b6b3', 'the-missing-trophy', $q$The Missing Trophy$q$, $q$لغز الكأس المختفية$q$, $q$On the morning of the science-fair awards, the golden trophy vanished from the glass display cabinet in the school hall. Follow the clues, listen to the witnesses and discover what really happened.$q$, $q$في صباح حفل جوائز معرض العلوم، اختفت الكأس الذهبية من خزانة العرض الزجاجية في قاعة المدرسة. تتبّع الآثار، واستمع إلى الشهود، واكتشف ما حدث فعلًا.$q$, 'FULL', 2, 8, 14, 'DRAFT', v_user, $q$MISSING_OBJECT$q$, 15, $q$It is ten to eight, and the hall is decorated with colourful flags for the science-fair ceremony. But the top shelf of the display cabinet is empty: the golden trophy with the red ribbon is gone! You have less than an hour before the ceremony begins. Can you solve the mystery?$q$, $q$الساعة الثامنة إلا عشر دقائق، والقاعة مزيّنة بالأعلام الملوّنة لحفل معرض العلوم. لكنّ الرفّ العلويّ في خزانة العرض فارغ، والكأس الذهبية ذات الشريط الأحمر لم تعد هناك! أمامك أقلّ من ساعة قبل بدء الحفل، فهل تكشف السرّ؟$q$, $q$Inspect the three locations, collect the clues, compare what the witnesses say with what you see, then work out where the trophy went and why.$q$, $q$افحص الأماكن الثلاثة، واجمع الأدلة، وقارن أقوال الشهود بما تراه، ثم حدّد أين ذهبت الكأس ولماذا.$q$, 'demo/detective/missing-trophy/cover.webp') on conflict (id) do nothing;
insert into detective_case_versions(id, case_id, version_number, status, created_by) values ('7140f402-c52a-580a-a937-3224b63a1817', '8b5f1606-cfc6-5bcf-9471-0a13d531b6b3', 1, 'DRAFT', v_user) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('ba114aea-6d83-5075-b94e-f62c6ea5ce73', '7140f402-c52a-580a-a937-3224b63a1817', 1, $q$The School Hall$q$, $q$قاعة المدرسة$q$, 'demo/detective/missing-trophy/scene-1.webp', $q$This is where the trophy used to shine behind the glass. The floor is still damp, a window is open and the flags are fluttering. Look carefully around the cabinet.$q$, $q$هنا كانت الكأس تلمع خلف الزجاج. الأرضية ما زالت رطبة، والنافذة مفتوحة، والأعلام ترفرف. ابحث جيدًا حول الخزانة.$q$) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('bbee00e5-bd05-57f4-aec0-8a642ab35e1f', '7140f402-c52a-580a-a937-3224b63a1817', 2, $q$The Corridor and the Back Door$q$, $q$الممرّ والباب الخلفي$q$, 'demo/detective/missing-trophy/scene-2.webp', $q$A long corridor with colourful lockers, the storage room door and a door that opens onto the school garden. Did anyone pass this way?$q$, $q$ممرّ طويل فيه الخزائن الملوّنة، وباب المخزن، وباب يُطلّ على حديقة المدرسة. هل مرّ أحدٌ من هنا؟$q$) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('d7e04fd6-9f9f-5768-8679-bc6ad2146d66', '7140f402-c52a-580a-a937-3224b63a1817', 3, $q$The Storage Room$q$, $q$غرفة المخزن$q$, 'demo/detective/missing-trophy/scene-3.webp', $q$A quiet room full of shelves and tools, lit by a hanging lamp. Some things here do not seem to be in their usual place.$q$, $q$غرفة هادئة مليئة بالرفوف والأدوات، يضيئها مصباح معلّق. بعض الأشياء هنا لا تبدو في مكانها المعتاد.$q$) on conflict (id) do nothing;
insert into detective_stages(id, version_id, stage_key, position, title, title_ar, unlock_rule) values ('5ad0a182-f531-5300-b46b-5dadee69c4f9', '7140f402-c52a-580a-a937-3224b63a1817', $q$observe$q$, 1, $q$Observe$q$, $q$لاحِظ$q$, $q${}$q$::jsonb) on conflict (id) do nothing;
insert into detective_stages(id, version_id, stage_key, position, title, title_ar, unlock_rule) values ('a3ab519c-d2e3-5c7d-abbf-d834c7d1e260', '7140f402-c52a-580a-a937-3224b63a1817', $q$connect$q$, 2, $q$Connect$q$, $q$اربِط$q$, $q${"requires_stage": "observe"}$q$::jsonb) on conflict (id) do nothing;
insert into detective_stages(id, version_id, stage_key, position, title, title_ar, unlock_rule) values ('533ca74e-d428-565f-a191-155124b7bd28', '7140f402-c52a-580a-a937-3224b63a1817', $q$conclude$q$, 3, $q$Conclude$q$, $q$استنتِج$q$, $q${"requires_stage": "connect"}$q$::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('60410c59-7df4-5192-8bc9-281e5c0718af', 'ba114aea-6d83-5075-b94e-f62c6ea5ce73', $q$lock-broken$q$, $q$A broken, rusty padlock$q$, $q$A broken, rusty padlock$q$, $q$قفل صدئ مكسور$q$, 35.94, 68.8, 5.5, 6.6, $q$On the floor near the display cabinet lies a small rusty padlock. Its loop is bent open, and a tiny metal piece that snapped off lies beside it.$q$, $q$على الأرض قرب خزانة العرض قفلٌ صغير صدئ، حلقته مفتوحة ومعوجّة، وبجانبه قطعة معدنية صغيرة انكسرت منه.$q$, $q$The cabinet was not opened with a key; its old lock broke because of rust. That explains why the trophy was no longer protected, and why a responsible person might want to move it somewhere safe.$q$, $q$الخزانة لم تُفتح بمفتاح، بل انكسر قفلها القديم من الصدأ. هذا يفسّر كيف أصبحت الكأس غير محميّة، ويجعل أي شخص مسؤول يرغب في نقلها إلى مكان آمن.$q$, $q$FACT$q$, 5, $q${}$q$::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('b59b57fa-7826-5dc9-bbe4-6a25405957ca', 'ba114aea-6d83-5075-b94e-f62c6ea5ce73', $q$wheel-tracks$q$, $q$Damp wheel tracks$q$, $q$Damp wheel tracks$q$, $q$آثار عجلات مبللة$q$, 48.6, 69.2, 33.67, 9.2, $q$Two thin, parallel, shiny lines on the damp floor start under the cabinet and head toward the side door.$q$, $q$خطّان رفيعان متوازيان ولامعان على الأرضية المبللة، يبدآن من تحت الخزانة ويتّجهان نحو الباب الجانبي.$q$, $q$Something with wheels, like a cleaning cart, rolled away from the cabinet across the freshly mopped floor. Someone on foot leaves shoe prints, not parallel lines.$q$, $q$شيءٌ له عجلات، مثل عربة تنظيف، مرّ من أمام الخزانة على الأرضية التي مُسحت للتو. الشخص الذي يمشي على قدميه يترك آثار أحذية لا خطوطًا متوازية.$q$, $q$OBSERVATION$q$, 5, $q${}$q$::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('10d9fc4f-af5c-5368-b632-108b4cf095c1', 'ba114aea-6d83-5075-b94e-f62c6ea5ce73', $q$karim-cap$q$, $q$A red cap with a star$q$, $q$A red cap with a star$q$, $q$قبعة حمراء عليها نجمة$q$, 19.98, 74.6, 8.68, 7.4, $q$On the wooden bench there is a red cap with a yellow star, next to a lunchbox and a water bottle.$q$, $q$على المقعد الخشبي قبعةٌ حمراء عليها نجمة صفراء، بجانب علبة غداء وقارورة ماء.$q$, $q$This is Karim's cap, which he always wears. It proves he came into the hall this morning, but being somewhere does not mean taking something from there.$q$, $q$هذه قبعة كريم التي لا يفارقها. وجودها في القاعة يثبت أنه دخلها هذا الصباح، لكنّ وجود شخصٍ في مكانٍ ما لا يعني أنه أخذ شيئًا منه.$q$, $q$FACT$q$, 3, $q${}$q$::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('11dcdbdc-99a4-59ec-b038-26e7c1381a7b', 'ba114aea-6d83-5075-b94e-f62c6ea5ce73', $q$open-window$q$, $q$The open window$q$, $q$The open window$q$, $q$النافذة المفتوحة$q$, 19.48, 10.2, 14.3, 39.2, $q$One of the hall windows is open. On its narrow sill, a pot of red flowers is still standing neatly in place.$q$, $q$إحدى نوافذ القاعة مفتوحة، وعلى حافّتها الضيّقة أصيص زهور حمراء ما زال واقفًا في مكانه بترتيب.$q$, $q$An open window makes us imagine a thief climbing in, but that is only an assumption. Anyone climbing through would have knocked the pot off the narrow sill, and the pot is perfectly fine.$q$, $q$النافذة المفتوحة تجعلنا نتخيّل لصًّا تسلّق منها، لكنّ هذا مجرّد افتراض. لو تسلّق أحدٌ من هنا لأسقط الأصيص عن الحافة الضيّقة، والأصيص سليم تمامًا.$q$, $q$ASSUMPTION$q$, 2, $q${}$q$::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('c9d0b952-0626-56c4-bb66-84192741db87', 'bbee00e5-bd05-57f4-aec0-8a642ab35e1f', $q$tracks-to-storage$q$, $q$The wheels lead to the storage room$q$, $q$The wheels lead to the storage room$q$, $q$العجلات تتّجه إلى المخزن$q$, 33.85, 62.8, 33.92, 16.6, $q$The same two parallel lines appear in the corridor, then turn straight toward the storage room door, which is slightly open.$q$, $q$الخطّان المتوازيان نفساهما يظهران في الممر، ثم ينعطفان مباشرةً نحو باب المخزن المفتوح قليلًا.$q$, $q$We can infer that the wheeled object that passed the cabinet travelled down the corridor into the storage room, not out through the garden door.$q$, $q$نستنتج أنّ الشيء ذا العجلات الذي مرّ بالخزانة سار في الممر ودخل المخزن، ولم يخرج من باب الحديقة.$q$, $q$INFERENCE$q$, 4, $q${"requires_evidence": ["b59b57fa-7826-5dc9-bbe4-6a25405957ca"]}$q$::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('abf4f23a-1ce1-56be-9ffa-d234b6c38ef0', 'bbee00e5-bd05-57f4-aec0-8a642ab35e1f', $q$cart-ribbon$q$, $q$Red ribbon on the cleaning cart$q$, $q$Red ribbon on the cleaning cart$q$, $q$شريط أحمر على عربة التنظيف$q$, 72.25, 47, 5.5, 7.4, $q$A small scrap of red ribbon is caught on the corner of the yellow cleaning cart parked beside the storage room door.$q$, $q$قطعة صغيرة من شريط أحمر عالقة في زاوية عربة التنظيف الصفراء الواقفة بجانب باب المخزن.$q$, $q$The golden trophy has a red ribbon tied on it, as shown in its picture in the hall. A scrap caught on the cart shows the trophy was carried on this cart.$q$, $q$الكأس الذهبية مربوط عليها شريط أحمر، كما في صورتها المعلّقة في القاعة. علوق قطعة منه بالعربة يدلّ على أنّ الكأس نُقلت على هذه العربة.$q$, $q$FACT$q$, 5, $q${}$q$::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('df602d07-f127-57a4-9291-26e3b0d53459', 'bbee00e5-bd05-57f4-aec0-8a642ab35e1f', $q$muddy-prints$q$, $q$Small muddy footprints$q$, $q$Small muddy footprints$q$, $q$آثار أقدام صغيرة موحلة$q$, 72.47, 68.8, 20.93, 23.8, $q$Small sneaker prints with garden mud start at the garden door and lead along the corridor toward the hall.$q$, $q$آثار حذاء رياضي صغير عليها طين الحديقة، تبدأ من باب الحديقة وتتّجه داخل الممر نحو القاعة.$q$, $q$Most likely these belong to a student who came from the garden, such as Karim. They show he walked toward the hall, but they are footprints, not wheel tracks, so they do not explain how the trophy moved.$q$, $q$على الأرجح هي آثار تلميذ جاء من الحديقة، مثل كريم. إنها تدلّ على أنه ذهب نحو القاعة، لكنها آثار أقدام وليست آثار عجلات، فهي لا تفسّر نقل الكأس.$q$, $q$PROBABILITY$q$, 2, $q${}$q$::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('c9808ea8-2128-5c76-a870-d4ec3e41b0c3', 'd7e04fd6-9f9f-5768-8679-bc6ad2146d66', $q$hidden-trophy$q$, $q$Something golden under a cloth$q$, $q$Something golden under a cloth$q$, $q$شكلٌ ذهبيّ تحت القماش$q$, 45.1, 43.4, 9.8, 17, $q$On the workbench, something is covered with a grey cloth, and a shiny golden handle peeks out from its side.$q$, $q$على طاولة العمل شيءٌ مغطّى بقطعة قماش رمادية، يطلّ من جانبها مقبض ذهبي لامع.$q$, $q$It is the missing trophy! It has been carefully covered to protect it from dust, not hidden in a bag or carried out of the school.$q$, $q$إنها الكأس المفقودة! وهي مغطّاة بعناية لحمايتها من الغبار، لا مخبّأة في حقيبة ولا محمولة خارج المدرسة.$q$, $q$FACT$q$, 5, $q${"requires_evidence": ["abf4f23a-1ce1-56be-9ffa-d234b6c38ef0"]}$q$::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('d5e5a02e-3eb5-5ea6-81e0-a6f0c8221510', 'd7e04fd6-9f9f-5768-8679-bc6ad2146d66', $q$polish-cloth$q$, $q$Polish tin and a gold-smudged rag$q$, $q$Polish tin and a gold-smudged rag$q$, $q$علبة ملمّع وقماشة ذهبية البقع$q$, 58.16, 55.25, 9.18, 5.5, $q$Next to the trophy there is an open tin of metal polish and a white rag with golden smudges.$q$, $q$بجانب الكأس علبة ملمّع للمعادن مفتوحة، وقطعة قماش بيضاء عليها بقع ذهبية.$q$, $q$Someone has been polishing something golden, getting the trophy ready to shine at the ceremony. That is the work of someone caring for the trophy, not someone trying to take it.$q$, $q$أحدهم كان يلمّع شيئًا ذهبيًا، أي أنه يجهّز الكأس لتلمع في الحفل. هذا عمل من يعتني بالكأس، لا من يريد أخذها.$q$, $q$OBSERVATION$q$, 3, $q${}$q$::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('d928d22e-f72f-5dcc-9e40-ddd7f538c9eb', 'd7e04fd6-9f9f-5768-8679-bc6ad2146d66', $q$new-lock$q$, $q$A new lock in its package$q$, $q$A new lock in its package$q$, $q$قفل جديد في غلافه$q$, 87.88, 28, 5.5, 11.2, $q$On the pegboard, among the hammer and screwdrivers, a new silver padlock is still in its plastic package.$q$, $q$على لوح الأدوات المثقّب، بين المطرقة والمفكّات، قفلٌ فضيّ جديد ما زال في غلافه البلاستيكي.$q$, $q$This lock was most likely brought to replace the broken cabinet lock. Whoever moved the trophy planned to fix the cabinet and put it back.$q$, $q$على الأرجح أُحضر هذا القفل ليحلّ محلّ قفل الخزانة المكسور. من نقل الكأس كان ينوي إصلاح الخزانة وإعادتها إليها.$q$, $q$PROBABILITY$q$, 4, $q${}$q$::jsonb) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('f0d8b665-cc5a-5ac7-bb03-e140974aad20', '7140f402-c52a-580a-a937-3224b63a1817', 'b59b57fa-7826-5dc9-bbe4-6a25405957ca', 'c9d0b952-0626-56c4-bb66-84192741db87', $q$SUPPORTS$q$, $q$The parallel lines in the hall continue along the corridor to the storage room door: they are traces of the same journey.$q$, $q$الخطّان المتوازيان في القاعة يكمّلان طريقهما في الممر حتى باب المخزن، فهما أثر الرحلة نفسها.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('aff80add-49ab-54e8-a2c3-b4d5ba5b0cd9', '7140f402-c52a-580a-a937-3224b63a1817', 'abf4f23a-1ce1-56be-9ffa-d234b6c38ef0', 'c9808ea8-2128-5c76-a870-d4ec3e41b0c3', $q$SUPPORTS$q$, $q$The ribbon on the cart links the cart to the trophy, and the trophy is indeed in the storage room where the cart is parked.$q$, $q$الشريط العالق بالعربة يربط العربة بالكأس، والكأس وُجدت فعلًا في المخزن الذي وقفت العربة عند بابه.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('0ec0aaec-a039-5e97-b9b8-1c7b34035fa4', '7140f402-c52a-580a-a937-3224b63a1817', 'b59b57fa-7826-5dc9-bbe4-6a25405957ca', '11dcdbdc-99a4-59ec-b038-26e7c1381a7b', $q$CONTRADICTS$q$, $q$The tracks show the trophy left on wheels through the door, which contradicts the idea that someone took it out through the window.$q$, $q$الآثار تُظهر أنّ الكأس غادرت على عجلات عبر الباب، وهذا يناقض فكرة أنّ أحدًا أخذها وخرج من النافذة.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('58303cf6-da17-5a5c-9bd0-fb361503cad8', '7140f402-c52a-580a-a937-3224b63a1817', '10d9fc4f-af5c-5368-b632-108b4cf095c1', 'df602d07-f127-57a4-9291-26e3b0d53459', $q$SUPPORTS$q$, $q$The cap in the hall and the footprints leading from the garden toward the hall both show that Karim entered the hall this morning.$q$, $q$القبعة في القاعة والآثار القادمة من الحديقة نحو القاعة تدلّان معًا على أنّ كريم دخل القاعة هذا الصباح.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('ee8eea73-e833-5131-8909-0c6fe9b7169f', '7140f402-c52a-580a-a937-3224b63a1817', '60410c59-7df4-5192-8bc9-281e5c0718af', 'd928d22e-f72f-5dcc-9e40-ddd7f538c9eb', $q$CONTEXTUAL$q$, $q$The new lock only makes sense once we know the old cabinet lock broke: it is the replacement.$q$, $q$القفل الجديد يُفهم فقط عندما نعرف أنّ قفل الخزانة القديم قد انكسر؛ إنه بديله.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('57c402ff-8582-5e45-86b2-c400a7277d4b', '7140f402-c52a-580a-a937-3224b63a1817', 'c9808ea8-2128-5c76-a870-d4ec3e41b0c3', 'd5e5a02e-3eb5-5ea6-81e0-a6f0c8221510', $q$TEMPORAL$q$, $q$The trophy reached the storage room first, and then the polishing began; that is why the polish and the rag are next to it on the bench.$q$, $q$وصلت الكأس إلى المخزن أولًا، ثم بدأ تلميعها؛ لذلك نجد الملمّع والقماشة بجانبها على الطاولة.$q$) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('6d239d70-bd23-5bd9-95a8-12b923908967', '7140f402-c52a-580a-a937-3224b63a1817', '5ad0a182-f531-5300-b46b-5dadee69c4f9', $q$MULTIPLE_CHOICE$q$, $q$What did you find on the floor near the display cabinet?$q$, $q$ماذا وجدتَ على الأرض قرب خزانة العرض؟$q$, $q$[{"id": "a", "text": "A broken, rusty padlock", "text_ar": "قفلًا صدئًا مكسورًا"}, {"id": "b", "text": "A golden key", "text_ar": "مفتاحًا ذهبيًا"}, {"id": "c", "text": "A black glove", "text_ar": "قفّازًا أسود"}, {"id": "d", "text": "A coin", "text_ar": "قطعة نقدية"}]$q$::jsonb, $q${"option_id": "a"}$q$::jsonb, '[]'::jsonb, $q$The rusty lock lies on the floor with its loop open: it broke, it was not opened with a key.$q$, $q$القفل الصدئ ملقى على الأرض وحلقته مفتوحة؛ لقد انكسر ولم يُفتح بمفتاح.$q$, array['60410c59-7df4-5192-8bc9-281e5c0718af'::uuid]::uuid[], 10, -3, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('f1e4b5dd-eb83-5079-9024-0f751b9adf51', '7140f402-c52a-580a-a937-3224b63a1817', '5ad0a182-f531-5300-b46b-5dadee69c4f9', $q$TRUE_FALSE$q$, $q$The flower pot on the open window sill is knocked over and broken.$q$, $q$أصيص الزهور على حافة النافذة المفتوحة مقلوب ومكسور.$q$, $q$[]$q$::jsonb, $q${"value": "false"}$q$::jsonb, '[]'::jsonb, $q$The pot is standing neatly in place; anyone climbing through the window would have knocked it off.$q$, $q$الأصيص واقف في مكانه بترتيب، ولو تسلّق أحدٌ من النافذة لأسقطه.$q$, array['11dcdbdc-99a4-59ec-b038-26e7c1381a7b'::uuid]::uuid[], 10, -3, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('d391b4ab-77bf-5362-9425-c1a4ea2121a0', '7140f402-c52a-580a-a937-3224b63a1817', '5ad0a182-f531-5300-b46b-5dadee69c4f9', $q$MULTIPLE_CHOICE$q$, $q$What kind of marks start under the display cabinet?$q$, $q$ما نوع الآثار التي تبدأ من تحت خزانة العرض؟$q$, $q$[{"id": "a", "text": "Big boot prints", "text_ar": "آثار أحذية كبيرة"}, {"id": "b", "text": "Two damp parallel lines made by wheels", "text_ar": "خطّان متوازيان مبلّلان من عجلات"}, {"id": "c", "text": "Drops of coloured paint", "text_ar": "قطرات طلاء ملوّن"}, {"id": "d", "text": "Cat paw prints", "text_ar": "آثار أقدام قطة"}]$q$::jsonb, $q${"option_id": "b"}$q$::jsonb, '[]'::jsonb, $q$Thin parallel lines on a damp floor are left by wheels, not by feet.$q$, $q$الخطّان الرفيعان المتوازيان على الأرض المبللة تتركهما العجلات، لا الأقدام.$q$, array['b59b57fa-7826-5dc9-bbe4-6a25405957ca'::uuid]::uuid[], 10, -3, 3) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('4f1367c7-ed83-5c9c-8bfd-4246903b59cb', '7140f402-c52a-580a-a937-3224b63a1817', 'a3ab519c-d2e3-5c7d-abbf-d834c7d1e260', $q$EVIDENCE_RELATIONSHIP$q$, $q$How are the wheel tracks in the hall related to the tracks leading to the storage room in the corridor?$q$, $q$ما العلاقة بين آثار العجلات في القاعة والآثار المتّجهة إلى المخزن في الممر؟$q$, $q$[]$q$::jsonb, $q${"from": "b59b57fa-7826-5dc9-bbe4-6a25405957ca", "to": "c9d0b952-0626-56c4-bb66-84192741db87", "relation": "SUPPORTS"}$q$::jsonb, '[]'::jsonb, $q$They are the same tracks continuing; the hall tracks support the idea that the wheeled object ended up in the storage room.$q$, $q$إنها الآثار نفسها تكمل طريقها؛ آثار القاعة تدعم أنّ الشيء ذا العجلات انتهى في المخزن.$q$, array['b59b57fa-7826-5dc9-bbe4-6a25405957ca'::uuid,'c9d0b952-0626-56c4-bb66-84192741db87'::uuid]::uuid[], 15, -5, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('f2d781bb-d1f3-56f7-9ab0-f9b1d4f2e736', '7140f402-c52a-580a-a937-3224b63a1817', 'a3ab519c-d2e3-5c7d-abbf-d834c7d1e260', $q$EVIDENCE_RELATIONSHIP$q$, $q$How do the wheel tracks relate to the idea that someone took the trophy out through the open window?$q$, $q$ما العلاقة بين آثار العجلات وفكرة أنّ أحدًا أخذ الكأس عبر النافذة المفتوحة؟$q$, $q$[]$q$::jsonb, $q${"from": "b59b57fa-7826-5dc9-bbe4-6a25405957ca", "to": "11dcdbdc-99a4-59ec-b038-26e7c1381a7b", "relation": "CONTRADICTS"}$q$::jsonb, '[]'::jsonb, $q$The tracks lead to the door, not to the window, so they contradict the window idea.$q$, $q$الآثار تقود إلى الباب لا إلى النافذة، فهي تناقض فكرة الخروج من النافذة.$q$, array['b59b57fa-7826-5dc9-bbe4-6a25405957ca'::uuid,'11dcdbdc-99a4-59ec-b038-26e7c1381a7b'::uuid]::uuid[], 15, -5, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('518d56eb-5549-5ef8-a594-0bcf0912a168', '7140f402-c52a-580a-a937-3224b63a1817', 'a3ab519c-d2e3-5c7d-abbf-d834c7d1e260', $q$TRUE_FALSE$q$, $q$Karim's statement "I never went into the hall this morning" is true.$q$, $q$قول كريم: «لم أدخل القاعة أبدًا هذا الصباح» قولٌ صحيح.$q$, $q$[]$q$::jsonb, $q${"value": "false"}$q$::jsonb, '[]'::jsonb, $q$His red star cap is on the bench in the hall, and his muddy footprints lead from the garden toward the hall.$q$, $q$قبعته الحمراء ذات النجمة موجودة على مقعد القاعة، وآثار أقدامه الموحلة تتّجه من الحديقة نحو القاعة.$q$, array['10d9fc4f-af5c-5368-b632-108b4cf095c1'::uuid,'df602d07-f127-57a4-9291-26e3b0d53459'::uuid]::uuid[], 15, -5, 3) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('639b4cd6-dfe7-59e3-9536-034ea2a41fa1', '7140f402-c52a-580a-a937-3224b63a1817', 'a3ab519c-d2e3-5c7d-abbf-d834c7d1e260', $q$MULTIPLE_CHOICE$q$, $q$What does the red ribbon caught on the cleaning cart tell us?$q$, $q$علامَ يدلّ الشريط الأحمر العالق بعربة التنظيف؟$q$, $q$[{"id": "a", "text": "Someone decorated the cart for the ceremony", "text_ar": "أنّ أحدهم زيّن العربة للحفل"}, {"id": "b", "text": "It fell off Karim's cap", "text_ar": "أنّه سقط من قبعة كريم"}, {"id": "c", "text": "The trophy was carried on the cleaning cart", "text_ar": "أنّ الكأس نُقلت على عربة التنظيف"}, {"id": "d", "text": "The cart is brand new", "text_ar": "أنّ العربة جديدة"}]$q$::jsonb, $q${"option_id": "c"}$q$::jsonb, '[]'::jsonb, $q$The trophy wears a red ribbon, as in its picture, and a scrap of it got caught on the cart while it was being moved.$q$, $q$الكأس عليها شريط أحمر كما في صورتها، وقطعة منه علقت بالعربة أثناء نقلها.$q$, array['abf4f23a-1ce1-56be-9ffa-d234b6c38ef0'::uuid]::uuid[], 15, -5, 4) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('782eebca-562a-5b8c-9824-7d13a972afc6', '7140f402-c52a-580a-a937-3224b63a1817', 'a3ab519c-d2e3-5c7d-abbf-d834c7d1e260', $q$MULTIPLE_CHOICE$q$, $q$Why is there most likely a new, packaged lock in the storage room?$q$, $q$لماذا يوجد قفل جديد في غلافه داخل المخزن على الأرجح؟$q$, $q$[{"id": "a", "text": "To lock the garden door", "text_ar": "ليُقفل به باب الحديقة"}, {"id": "b", "text": "To replace the broken cabinet lock", "text_ar": "ليحلّ محلّ قفل الخزانة المكسور"}, {"id": "c", "text": "As a prize for the winner", "text_ar": "ليكون جائزة للفائز"}, {"id": "d", "text": "To lock Karim's bag", "text_ar": "ليُقفل به حقيبة كريم"}]$q$::jsonb, $q${"option_id": "b"}$q$::jsonb, '[]'::jsonb, $q$The cabinet lock broke, and whoever is looking after the trophy needs a new lock to put it back safely.$q$, $q$قفل الخزانة انكسر، ومن يعتني بالكأس سيحتاج قفلًا جديدًا لإعادتها إلى الخزانة بأمان.$q$, array['d928d22e-f72f-5dcc-9e40-ddd7f538c9eb'::uuid,'60410c59-7df4-5192-8bc9-281e5c0718af'::uuid]::uuid[], 15, -5, 5) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('00a07c57-c651-585f-92c2-1723bff734b3', '7140f402-c52a-580a-a937-3224b63a1817', '533ca74e-d428-565f-a191-155124b7bd28', $q$FINAL_CONCLUSION$q$, $q$What really happened to the golden trophy?$q$, $q$ماذا حدث للكأس الذهبية حقًّا؟$q$, $q$[{"id": "a", "text": "Uncle Saeed found the lock broken, so he moved the trophy on his cart to the storage room to keep it safe and polish it", "text_ar": "العم سعيد وجد القفل مكسورًا، فنقل الكأس على عربته إلى المخزن ليحميها ويلمّعها"}, {"id": "b", "text": "Karim took the trophy and hid it because he wants to win", "text_ar": "كريم أخذ الكأس وخبّأها لأنه يريد الفوز"}, {"id": "c", "text": "A thief climbed in through the open window and ran off with the trophy", "text_ar": "لصٌّ تسلّق من النافذة المفتوحة وهرب بالكأس"}, {"id": "d", "text": "There is not enough evidence", "text_ar": "لا توجد أدلة كافية"}]$q$::jsonb, $q${"option_id": "a"}$q$::jsonb, '[]'::jsonb, $q$The broken lock, the wheel tracks from the cabinet to the storage room, the ribbon on the cleaning cart, and the covered trophy beside the polish and the new lock all point to Uncle Saeed, who was protecting the trophy, not stealing it.$q$, $q$القفل المكسور، وآثار العجلات من الخزانة إلى المخزن، والشريط على عربة التنظيف، والكأس المغطّاة بجانب الملمّع والقفل الجديد؛ كلّها تقود إلى العم سعيد الذي كان يحمي الكأس لا يسرقها.$q$, array['60410c59-7df4-5192-8bc9-281e5c0718af'::uuid,'b59b57fa-7826-5dc9-bbe4-6a25405957ca'::uuid,'c9d0b952-0626-56c4-bb66-84192741db87'::uuid,'abf4f23a-1ce1-56be-9ffa-d234b6c38ef0'::uuid,'c9808ea8-2128-5c76-a870-d4ec3e41b0c3'::uuid,'d5e5a02e-3eb5-5ea6-81e0-a6f0c8221510'::uuid,'d928d22e-f72f-5dcc-9e40-ddd7f538c9eb'::uuid]::uuid[], 25, -5, 1) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('c27d7122-59da-51ca-af2c-8728217c6733', '7140f402-c52a-580a-a937-3224b63a1817', $q$Uncle Saeed$q$, $q$العم سعيد$q$, $q$A kind man who has worked at the school for twenty years. He pushes his yellow cart everywhere to keep the school clean and shiny.$q$, $q$رجلٌ طيّب يعمل في المدرسة منذ عشرين عامًا، ويدفع عربته الصفراء في كل مكان ليُبقي المدرسة نظيفة ولامعة.$q$, $q$عامل النظافة في المدرسة$q$, $q$School caretaker$q$, '[]'::jsonb, $q$يقول إنه قضى الصباح في مسح القاعة ثم في العمل داخل المخزن.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('0dffe69b-d030-52d1-9157-1cbe2cc4ef1c', 'c27d7122-59da-51ca-af2c-8728217c6733', $q$I arrived at seven o'clock sharp and mopped the whole hall floor.$q$, $q$وصلتُ في السابعة تمامًا ومسحتُ أرضية القاعة كلّها.$q$, $q$TRUE$q$, '{}'::uuid[], $q$The floor is still damp, and the wheel tracks showed up because they crossed a wet floor.$q$, $q$الأرضية ما زالت رطبة، وآثار العجلات ظهرت لأنها مرّت على أرضٍ مبللة.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('fb2a91d3-c950-501c-afb2-d29952b6273a', 'c27d7122-59da-51ca-af2c-8728217c6733', $q$After that I went to the storage room to finish some important jobs before the ceremony.$q$, $q$بعد ذلك ذهبتُ إلى المخزن لأنجز بعض الأعمال المهمّة قبل الحفل.$q$, $q$INCOMPLETE$q$, array['abf4f23a-1ce1-56be-9ffa-d234b6c38ef0'::uuid,'c9808ea8-2128-5c76-a870-d4ec3e41b0c3'::uuid]::uuid[], $q$What he says is true but incomplete: he did not mention that the "important job" was protecting and polishing the trophy after he found its lock broken. He forgot to tell anyone.$q$, $q$كلامه صحيح لكنه ناقص: لم يذكر أنّ «العمل المهم» كان حماية الكأس وتلميعها بعد أن وجد قفلها مكسورًا، فقد نسي أن يُخبر أحدًا.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('f762909e-bf5a-5229-9871-dfca0059f3da', '7140f402-c52a-580a-a937-3224b63a1817', $q$Karim$q$, $q$كريم$q$, $q$A twelve-year-old student who is very excited about the science fair and never takes off his red cap with the yellow star. His plant-growth experiment is planted in the school garden.$q$, $q$تلميذ في الثانية عشرة، متحمّس جدًا لمعرض العلوم، ولا يفارق قبعته الحمراء ذات النجمة الصفراء. تجربته عن نموّ النباتات مزروعة في حديقة المدرسة.$q$, $q$تلميذ مشارك في معرض العلوم$q$, $q$Student taking part in the science fair$q$, '[]'::jsonb, $q$يقول إنه كان في الحديقة طوال الصباح يتفقّد نباتاته.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('29432c8f-7ecd-565a-88ea-645891fa3674', 'f762909e-bf5a-5229-9871-dfca0059f3da', $q$I never went into the hall this morning. I was in the garden the whole time.$q$, $q$لم أدخل القاعة أبدًا هذا الصباح، كنتُ في الحديقة طوال الوقت.$q$, $q$FALSE$q$, array['10d9fc4f-af5c-5368-b632-108b4cf095c1'::uuid,'df602d07-f127-57a4-9291-26e3b0d53459'::uuid]::uuid[], $q$His cap is on the bench in the hall, and his muddy prints lead from the garden toward the hall. He did go in, saw the empty cabinet, got scared of being blamed and did not tell the truth. Being honest would have saved everyone time!$q$, $q$قبعته على مقعد القاعة، وآثاره الموحلة تتّجه من الحديقة نحو القاعة. لقد دخل القاعة، ورأى الخزانة فارغة فخاف أن يُتّهم، فقال غير الحقيقة. الصدق كان سيوفّر على الجميع وقتًا!$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('ccf287e9-49dc-50a5-941a-c7e3f618cdb3', 'f762909e-bf5a-5229-9871-dfca0059f3da', $q$My plant-growth experiment is in the school garden.$q$, $q$تجربتي عن نموّ النباتات موجودة في حديقة المدرسة.$q$, $q$TRUE$q$, '{}'::uuid[], $q$That explains the mud on his shoes: he came in from the garden.$q$, $q$هذا يفسّر الطين على حذائه؛ فقد جاء من الحديقة.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('dc507a72-17e6-5b86-9357-986a5bba7242', '7140f402-c52a-580a-a937-3224b63a1817', $q$Ms. Layla$q$, $q$المعلّمة ليلى$q$, $q$A cheerful, organised teacher who hung the colourful flags herself. She was the first to notice the trophy was missing.$q$, $q$معلّمة مرحة ومنظّمة، علّقت الأعلام الملوّنة بنفسها، وهي أول من لاحظ اختفاء الكأس.$q$, $q$معلّمة العلوم ومنظّمة الحفل$q$, $q$Science teacher and ceremony organiser$q$, '[]'::jsonb, $q$تقول إنها وصلت إلى القاعة في الثامنة إلا عشر دقائق.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('92075b3c-f1cd-5015-93bf-9f7f5b44d9e3', 'dc507a72-17e6-5b86-9357-986a5bba7242', $q$When I arrived at ten to eight, I found the cabinet empty and the lock on the floor.$q$, $q$عندما وصلتُ في الثامنة إلا عشر دقائق، وجدتُ الخزانة فارغة والقفل على الأرض.$q$, $q$TRUE$q$, '{}'::uuid[], $q$The broken lock is on the floor just as she said, and the hall clock shows ten to eight.$q$, $q$القفل المكسور على الأرض كما قالت، وساعة القاعة تشير إلى الثامنة إلا عشر دقائق.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('38dcbb47-3dab-5818-b770-3af0d89f5b5d', 'dc507a72-17e6-5b86-9357-986a5bba7242', $q$I opened the window yesterday afternoon to air the hall, and I forgot to close it.$q$, $q$فتحتُ النافذة أمس بعد الظهر لتهوية القاعة، ونسيتُ أن أغلقها.$q$, $q$TRUE$q$, '{}'::uuid[], $q$This explains the open window, and the undisturbed pot on its sill confirms no one climbed through it.$q$, $q$هذا يفسّر النافذة المفتوحة، والأصيص السليم على حافتها يؤكّد أنّ أحدًا لم يتسلّق منها.$q$) on conflict (id) do nothing;
insert into detective_timeline_events(id, version_id, event_key, label, label_ar, window_key, position) values ('1ba8bbdb-e463-58d6-b898-1d5e8a1866ca', '7140f402-c52a-580a-a937-3224b63a1817', $q$t-mop$q$, $q$Uncle Saeed arrives and starts mopping the hall floor$q$, $q$العم سعيد يصل ويبدأ مسح أرضية القاعة$q$, $q$07:00$q$, 1) on conflict (id) do nothing;
insert into detective_timeline_events(id, version_id, event_key, label, label_ar, window_key, position) values ('4c2f990a-7b84-5365-a933-80cc02260201', '7140f402-c52a-580a-a937-3224b63a1817', $q$t-wheels$q$, $q$Wheels leave tracks on the wet floor from the cabinet toward the storage room$q$, $q$عجلات تترك آثارًا على الأرضية المبللة من الخزانة نحو المخزن$q$, $q$07:15$q$, 2) on conflict (id) do nothing;
insert into detective_timeline_events(id, version_id, event_key, label, label_ar, window_key, position) values ('94973a29-7784-5651-b81d-2b3a4a2622fd', '7140f402-c52a-580a-a937-3224b63a1817', $q$t-karim$q$, $q$Karim comes in through the garden door and passes through the hall$q$, $q$كريم يدخل من باب الحديقة ويمرّ بالقاعة$q$, $q$07:40$q$, 3) on conflict (id) do nothing;
insert into detective_timeline_events(id, version_id, event_key, label, label_ar, window_key, position) values ('bbc974ab-4cbb-5e86-968b-6fd408780c9d', '7140f402-c52a-580a-a937-3224b63a1817', $q$t-layla$q$, $q$Ms. Layla discovers the cabinet is empty$q$, $q$المعلّمة ليلى تكتشف أنّ الخزانة فارغة$q$, $q$07:50$q$, 4) on conflict (id) do nothing;
insert into detective_timeline_events(id, version_id, event_key, label, label_ar, window_key, position) values ('64fc8954-ae91-5e7a-9e03-016949e7a834', '7140f402-c52a-580a-a937-3224b63a1817', $q$t-ceremony$q$, $q$The awards ceremony is due to begin$q$, $q$موعد بدء حفل توزيع الجوائز$q$, $q$08:30$q$, 5) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('50450760-7b1e-5ee3-ab76-f93d34d8f818', '7140f402-c52a-580a-a937-3224b63a1817', '5ad0a182-f531-5300-b46b-5dadee69c4f9', $q$Look carefully at the floor around the display cabinet; small things can fall and go unnoticed.$q$, $q$انظر جيدًا إلى الأرض حول خزانة العرض؛ فالأشياء الصغيرة قد تسقط وتختفي عن الأنظار.$q$, '{}'::jsonb, -2, 1) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('c3ccded5-3458-5c2d-b1c5-b702dad63f58', '7140f402-c52a-580a-a937-3224b63a1817', '5ad0a182-f531-5300-b46b-5dadee69c4f9', $q$Something shiny and damp starts under the cabinet… follow it with your eyes to see where it goes.$q$, $q$تحت الخزانة يبدأ شيءٌ لامع ومبلّل على الأرض… اتبعه بعينيك إلى أين يذهب.$q$, '{}'::jsonb, -2, 2) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('360bf5cf-2e69-5ac2-bd5a-35e67e86e49a', '7140f402-c52a-580a-a937-3224b63a1817', 'a3ab519c-d2e3-5c7d-abbf-d834c7d1e260', $q$Compare what you saw in the hall with what you saw in the corridor: does something appear in both places?$q$, $q$قارن ما رأيته في القاعة بما رأيته في الممر: هل يتكرّر شيءٌ ما في المكانين؟$q$, '{}'::jsonb, -2, 1) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('63e20386-3cd9-5a6a-ae24-2d201869fbc4', '7140f402-c52a-580a-a937-3224b63a1817', 'a3ab519c-d2e3-5c7d-abbf-d834c7d1e260', $q$Remember the ribbon colour in the trophy picture on the hall wall, then look for the same colour near the storage room door.$q$, $q$تذكّر لون الشريط في صورة الكأس المعلّقة على حائط القاعة، ثم ابحث عن اللون نفسه قرب باب المخزن.$q$, '{}'::jsonb, -2, 2) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('e3242063-0f75-5ed1-a0f0-dcc79e5eeb5a', '7140f402-c52a-580a-a937-3224b63a1817', '533ca74e-d428-565f-a191-155124b7bd28', $q$Ask yourself: who at school uses something with wheels every morning?$q$, $q$اسأل نفسك: مَن في المدرسة يستخدم شيئًا له عجلات كلّ صباح؟$q$, '{}'::jsonb, -2, 1) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('2f638833-606e-5ccb-91f0-5d3af92dc649', '7140f402-c52a-580a-a937-3224b63a1817', '533ca74e-d428-565f-a191-155124b7bd28', $q$Look at the tools next to what you found in the storage room: what was their owner planning to do?$q$, $q$تأمّل الأدوات الموجودة بجانب ما وجدته في المخزن: ماذا كان ينوي صاحبها أن يفعل؟$q$, '{}'::jsonb, -2, 2) on conflict (id) do nothing;
insert into detective_solutions(id, version_id, public_reveal, public_reveal_ar, solution_key, alternative_hypotheses, educational_explanation, educational_explanation_ar) values ('7d9764e5-7628-56df-bfe7-94241f9d0120', '7140f402-c52a-580a-a937-3224b63a1817', $q$The trophy was not stolen! At seven in the morning, Uncle Saeed was mopping the hall when he found the old cabinet lock broken on the floor. Worried the trophy might go missing before the ceremony, he put it on his cleaning cart and wheeled it to the storage room to keep it safe and polish it. He also fetched a new lock for the cabinet, but he forgot to tell anyone.$q$, $q$الكأس لم تُسرق! في السابعة صباحًا كان العم سعيد يمسح القاعة، فوجد قفل الخزانة القديم مكسورًا على الأرض. خاف أن تضيع الكأس قبل الحفل، فوضعها على عربة التنظيف ونقلها إلى المخزن ليحفظها ويلمّعها، وأحضر قفلًا جديدًا ليركّبه للخزانة، لكنه نسي أن يُخبر أحدًا.$q$, $q${"final_question": "00a07c57-c651-585f-92c2-1723bff734b3"}$q$::jsonb, $q$[{"en": "Karim took the trophy and hid it because he wants to win.", "ar": "كريم أخذ الكأس وخبّأها لأنه يريد الفوز.", "why_wrong_en": "His cap and footprints only prove he entered the hall. The trophy left on wheels, the ribbon is on the cleaning cart, not on Karim's things, and the trophy was found being polished in the storage room.", "why_wrong_ar": "قبعته وآثار أقدامه تثبت أنه دخل القاعة فقط. الكأس غادرت على عجلات، والشريط على عربة التنظيف لا على أغراض كريم، والكأس وُجدت في المخزن تُلمَّع."}, {"en": "A thief climbed in through the open window and ran off with the trophy.", "ar": "لصٌّ تسلّق من النافذة المفتوحة وهرب بالكأس.", "why_wrong_en": "The flower pot on the narrow sill is still in place, Ms. Layla opened the window yesterday for fresh air, and the tracks lead to the storage room, not to the window.", "why_wrong_ar": "أصيص الزهور على الحافة الضيّقة سليم في مكانه، والمعلّمة ليلى فتحت النافذة أمس للتهوية، والآثار تقود إلى المخزن لا إلى النافذة."}, {"en": "There is not enough evidence to know what happened.", "ar": "لا توجد أدلة كافية لمعرفة ما حدث.", "why_wrong_en": "The chain of clues is complete from the cabinet to the storage room, and the trophy itself was found there.", "why_wrong_ar": "سلسلة الأدلة كاملة من الخزانة حتى المخزن، بل إنّ الكأس نفسها وُجدت هناك."}]$q$::jsonb, $q$The broken lock explains why the trophy was no longer protected. The damp wheel tracks start at the cabinet and run through the corridor to the storage room door, and the cleaning cart parked there has a scrap of the trophy's red ribbon on it. In the storage room the trophy is carefully covered, with polish, a gold-smudged rag and a new replacement lock beside it. Karim did not tell the truth because he was scared, but his traces are footprints, not wheel tracks, and the open window was only a misleading assumption.$q$, $q$القفل المكسور يفسّر لماذا لم تعد الكأس محميّة. آثار العجلات المبللة تبدأ من الخزانة وتمرّ في الممر حتى باب المخزن، وعلى عربة التنظيف الواقفة هناك قطعة من شريط الكأس الأحمر. وفي المخزن وجدنا الكأس مغطّاة بعناية، وبجانبها ملمّع وقماشة ذهبية البقع، وقفل جديد بديل للمكسور. أمّا كريم فقد قال غير الحقيقة لأنه خاف، لكنّ أدلّته آثار أقدام لا عجلات، والنافذة المفتوحة كانت مجرّد افتراض مضلِّل.$q$) on conflict (id) do nothing;
